CREATE TABLE public.growth_prospects (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation text NOT NULL CHECK (length(organisation) BETWEEN 1 AND 200), slug text UNIQUE NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 100), segment text NOT NULL DEFAULT 'clinic' CHECK (segment IN ('clinic','concierge','family-office','international')), factual_context text NOT NULL DEFAULT '' CHECK(length(factual_context)<=2000), source_urls text[] NOT NULL DEFAULT '{}', contact_name text NOT NULL DEFAULT '' CHECK(length(contact_name)<=200), email text NOT NULL DEFAULT '' CHECK(length(email)<=255), claim_verification_state text NOT NULL DEFAULT 'unverified' CHECK(claim_verification_state IN ('unverified','vetted')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','contacted','responded','application','approved','declined','archived')), partner_type text NOT NULL DEFAULT 'clinic' CHECK(partner_type IN ('clinic','concierge','other')), published boolean NOT NULL DEFAULT false, suppressed boolean NOT NULL DEFAULT false, suppression_reason text NOT NULL DEFAULT '' CHECK(length(suppression_reason)<=1000), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.growth_prospects TO authenticated;
GRANT ALL ON public.growth_prospects TO service_role;
ALTER TABLE public.growth_prospects ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_prospects_admin ON public.growth_prospects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.growth_applications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prospect_id uuid NOT NULL REFERENCES public.growth_prospects(id), company text NOT NULL CHECK(length(company) BETWEEN 1 AND 200), work_email text NOT NULL CHECK(length(work_email)<=255 AND work_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), role text NOT NULL CHECK(length(role) BETWEEN 1 AND 200), express_agreement boolean NOT NULL DEFAULT false, agreement_version text NOT NULL DEFAULT 'growth-trial-v1', agreement_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved_pending_setup','declined')), identity_verified boolean NOT NULL DEFAULT false, identity_evidence text NOT NULL DEFAULT '' CHECK(length(identity_evidence)<=2000), signed_terms_confirmed boolean NOT NULL DEFAULT false, terms_reference text NOT NULL DEFAULT '' CHECK(length(terms_reference)<=2000), decision_note text NOT NULL DEFAULT '' CHECK(length(decision_note)<=2000), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT growth_approval_requires_evidence CHECK(status <> 'approved_pending_setup' OR (identity_verified AND signed_terms_confirmed AND length(trim(identity_evidence))>0 AND length(trim(terms_reference))>0 AND reviewed_by IS NOT NULL))
);
GRANT SELECT ON public.growth_applications TO authenticated;
GRANT ALL ON public.growth_applications TO service_role;
ALTER TABLE public.growth_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_applications_admin_read ON public.growth_applications FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.growth_preview_daily_views (
 prospect_id uuid NOT NULL REFERENCES public.growth_prospects(id), day date NOT NULL DEFAULT current_date, views bigint NOT NULL DEFAULT 0, PRIMARY KEY(prospect_id,day)
);
GRANT SELECT ON public.growth_preview_daily_views TO authenticated;
GRANT ALL ON public.growth_preview_daily_views TO service_role;
ALTER TABLE public.growth_preview_daily_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_views_admin_read ON public.growth_preview_daily_views FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.growth_distribution_partners (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation text NOT NULL CHECK(length(organisation) BETWEEN 1 AND 200), contact_name text NOT NULL DEFAULT '' CHECK(length(contact_name)<=200), email text NOT NULL DEFAULT '' CHECK(length(email)<=255), network_size_evidence text NOT NULL DEFAULT '' CHECK(length(network_size_evidence)<=2000), source_urls text[] NOT NULL DEFAULT '{}', opportunity text NOT NULL DEFAULT '' CHECK(length(opportunity)<=2000), follow_up date, agreement_status text NOT NULL DEFAULT 'not_started' CHECK(agreement_status IN ('not_started','discussing','sent','signed','declined')), suppressed boolean NOT NULL DEFAULT false, notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.growth_distribution_partners TO authenticated;
GRANT ALL ON public.growth_distribution_partners TO service_role;
ALTER TABLE public.growth_distribution_partners ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_distribution_admin ON public.growth_distribution_partners FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.get_growth_preview(_slug text) RETURNS TABLE(id uuid, organisation text, slug text, segment text, factual_context text, source_urls text[], partner_type text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id,p.organisation,p.slug,p.segment,p.factual_context,p.source_urls,p.partner_type FROM public.growth_prospects p WHERE p.slug=_slug AND p.published AND NOT p.suppressed AND p.claim_verification_state='vetted' AND p.status <> 'archived' LIMIT 1; $$;
REVOKE ALL ON FUNCTION public.get_growth_preview(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_growth_preview(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.record_growth_preview_view(_slug text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE pid uuid; BEGIN SELECT p.id INTO pid FROM public.growth_prospects p WHERE p.slug=_slug AND p.published AND NOT p.suppressed AND p.claim_verification_state='vetted' AND p.status <> 'archived'; IF pid IS NOT NULL THEN INSERT INTO public.growth_preview_daily_views(prospect_id,day,views) VALUES(pid,current_date,1) ON CONFLICT(prospect_id,day) DO UPDATE SET views=growth_preview_daily_views.views+1; END IF; END; $$;
REVOKE ALL ON FUNCTION public.record_growth_preview_view(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_growth_preview_view(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.submit_growth_application(_slug text,_company text,_work_email text,_name text,_role text,_agreement boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE pid uuid; em text := lower(trim(_work_email)); BEGIN IF _agreement IS DISTINCT FROM true OR length(trim(_company)) NOT BETWEEN 1 AND 200 OR length(trim(_name)) NOT BETWEEN 1 AND 200 OR length(trim(_role)) NOT BETWEEN 1 AND 200 OR em IS NULL OR length(em)>255 OR em !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'invalid_application'; END IF; SELECT p.id INTO pid FROM public.growth_prospects p WHERE p.slug=_slug AND p.published AND NOT p.suppressed AND p.claim_verification_state='vetted' AND p.status <> 'archived'; IF pid IS NULL THEN RAISE EXCEPTION 'preview_unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(em,97)); IF (SELECT count(*) FROM public.growth_applications a WHERE a.work_email=em AND a.created_at > now()-interval '1 day') < 5 THEN INSERT INTO public.growth_applications(prospect_id,company,work_email,name,role,express_agreement) VALUES(pid,trim(_company),em,trim(_name),trim(_role),true); UPDATE public.growth_prospects SET status='application',updated_at=now() WHERE id=pid AND status IN ('ready','contacted','responded'); END IF; RETURN jsonb_build_object('status','pending_verification'); END; $$;
REVOKE ALL ON FUNCTION public.submit_growth_application(text,text,text,text,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_growth_application(text,text,text,text,text,boolean) TO anon,authenticated,service_role;
CREATE FUNCTION public.review_growth_application(_id uuid,_decision text,_identity_verified boolean,_identity_evidence text,_signed_terms boolean,_terms_reference text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF _decision NOT IN ('approved_pending_setup','declined') OR _decision IS NULL OR length(coalesce(_identity_evidence,''))>2000 OR length(coalesce(_terms_reference,''))>2000 OR length(coalesce(_note,''))>2000 THEN RAISE EXCEPTION 'invalid_decision'; END IF; IF _decision='approved_pending_setup' AND (NOT coalesce(_identity_verified,false) OR NOT coalesce(_signed_terms,false) OR length(trim(coalesce(_identity_evidence,'')))=0 OR length(trim(coalesce(_terms_reference,'')))=0) THEN RAISE EXCEPTION 'verified_identity_and_signed_terms_required'; END IF; UPDATE public.growth_applications SET status=_decision,identity_verified=coalesce(_identity_verified,false),identity_evidence=coalesce(_identity_evidence,''),signed_terms_confirmed=coalesce(_signed_terms,false),terms_reference=coalesce(_terms_reference,''),decision_note=coalesce(_note,''),reviewed_by=auth.uid(),reviewed_at=now() WHERE id=_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'pending_application_not_found'; END IF; INSERT INTO public.admin_actions(admin_user_id,action_type,details_json) VALUES(auth.uid(),'growth_application_reviewed',jsonb_build_object('application_id',_id,'decision',_decision)); END; $$;
REVOKE ALL ON FUNCTION public.review_growth_application(uuid,text,boolean,text,boolean,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_growth_application(uuid,text,boolean,text,boolean,text,text) TO authenticated;
CREATE TRIGGER growth_prospects_updated_at BEFORE UPDATE ON public.growth_prospects FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();